using System.IO;
using System.Windows;
using System.Windows.Controls;
using Studio.Core;
namespace Studio.Desktop;
public partial class MainWindow
{
    async void SweepGeometrySmoke()=>await TryRuntime(async()=>
    {
        var output=Path.GetFullPath(".artifacts/sweep-geometry-desktop");Directory.CreateDirectory(output);var checks=new List<string>();await RunSweepGeometryUiSmoke(output,(passed,label)=>{if(!passed)throw new InvalidOperationException("UI check failed: "+label);checks.Add(label);});File.WriteAllText(Path.Combine(output,"ui-checks.json"),System.Text.Json.JsonSerializer.Serialize(new{checks},BehaviorDocument.JsonOptions));Application.Current.Shutdown(0);
    });
    async Task RunSweepGeometryUiSmoke(string output,Action<bool,string> check)
    {
        var previous=Snapshot();var selected=adapter.Catalog().Single(e=>e.Id=="Gordo, the Unwound");var supplied=File.ReadAllText(selected.SourceFile);
        const string source="using System.Linq;using TKR.WorldServer.logic.behaviors;namespace TKR.WorldServer.logic{public partial class BehaviorDb{private _ StudioSweepDesktop=()=>Behav().Init(\"Gordo, the Unwound\",StudioSweepDesktopRoot());static State StudioSweepDesktopRoot(){var shared=new BossSweepGeometry(Enumerable.Range(14,2).ToArray(),armCount:2,startAngle:10,refreshMs:100,startupMs:0);var history=Enumerable.Range(30,2).ToArray();return new State(\"bands\",new ClockSweep(shared),new CorridorPulse(shared,38,intervalMs:100,startupMs:0),new OrientationEcho(shared,history,delayMs:200,intervalMs:100));}}}";
        ApplyProject(previous with{Source=source,SourceFile=selected.SourceFile,EntityId=selected.Id,Identities=[],SourceDrafts=[],SelectedSourceFile=null,AdditionalSources=[],LockedNodes=[],CollapsedNodes=[],Layout=[],Player=previous.Player with{Invulnerable=true}},null);EditDefinition(document.Definitions.Single(d=>d.Definition!.Label=="StudioSweepDesktopRoot").EntityId);var clock=document.AllNodes.Single(n=>n.Kind=="ClockSweep");var pulse=document.AllNodes.Single(n=>n.Kind=="CorridorPulse");var echo=document.AllNodes.Single(n=>n.Kind=="OrientationEcho");SelectNode(clock.Id);
        check(sweepGeometryPanel is{IsExpanded:false}&&sweepGeometryInputs.Count==4,"Shared sweep geometry opens in a quiet collapsed inspector with exact source fields");var before=document.Source;var revision=document.Revision;sweepGeometryInputs["startAngle"].Text="45";sweepGeometryInputs["armCount"].Text="3";sweepGeometryApply!.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));
        check(document.Revision==revision+1&&new[]{clock.Id,pulse.Id,echo.Id}.All(id=>adapter.ReadSweepGeometry(document,document.Find(id))?.Geometry is{Angle:45,Arms:3}),"Actual geometry Apply updates the single source constructor for all three consumers");Undo(this,new());check(document.Source==before&&new[]{clock.Id,pulse.Id,echo.Id}.All(id=>document.Find(id).Id==id),"Workspace geometry Undo restores complete source and every consumer identity");Redo(this,new());check(adapter.ReadSweepGeometry(document,document.Find(echo.Id))?.Geometry is{Angle:45,Arms:3},"Workspace geometry Redo restores the shared echo view");
        document.LockedNodes.Add(echo.Id);var accepted=document.Source;var blocked=false;try{CommitSweepGeometry(clock.Id,document.Revision,new Dictionary<string,string>{{"startAngle","60"}});}catch(InvalidOperationException){blocked=true;}check(blocked&&document.Source==accepted,"A locked echo blocks geometry edits initiated from the clock controller");document.LockedNodes.Clear();SelectNode(clock.Id);var stale=false;try{CommitSweepGeometry(clock.Id,document.Revision-1,new Dictionary<string,string>{{"startAngle","60"}});}catch(InvalidOperationException){stale=true;}check(stale&&document.Source==accepted,"Stale shared geometry proposals reject without changing source");
        SourceFiles.SelectedItem=((SourceFileChoice[])SourceFiles.ItemsSource).Single(s=>Path.GetFullPath(s.Path).Equals(Path.GetFullPath(selected.SourceFile),StringComparison.OrdinalIgnoreCase));SourceEditor.Text+="\n// retained geometry draft";var draft=SourceEditor.Text;blocked=false;try{CommitSweepGeometry(clock.Id,document.Revision,new Dictionary<string,string>{{"startAngle","60"}});}catch(InvalidOperationException){blocked=true;}check(blocked&&document.Source==accepted&&SourceEditor.Text==draft,"Affected source drafts survive rejected shared geometry edits");DiscardSourceDraft(this,new());SelectNode(clock.Id);Inspector.Children.OfType<CheckBox>().Single().IsChecked=true;check(sweepGeometryApply?.IsEnabled==false&&sweepGeometryInputs.Values.All(i=>!i.IsEnabled),"Geometry fields and Apply honor the selected source lock");document.LockedNodes.Clear();SelectNode(clock.Id);sweepGeometryPanel!.IsExpanded=true;WorkspaceTabs.SelectedIndex=1;UpdateLayout();CaptureView(this,Path.Combine(output,"shared-sweep-geometry.png"));
        var saved=Path.Combine(output,"geometry.rbs");BehaviorDocument.Save(saved,Snapshot());ApplyProject(BehaviorDocument.Load(saved),saved);check(adapter.ReadSweepGeometry(document,document.Find(clock.Id))?.Geometry is{Angle:45,Arms:3},"Reopening retains shared geometry and controller identities");check(await StartSessionAsync(),"Play executes the accepted original sweep/pulse/echo factory");running=false;await session!.AdvanceAsync(new(),400);UpdateSession();check(session.Shots.Where(s=>s.Index is 14 or 15).All(s=>s.Count==3)&&Math.Abs(session.Shots.First().Angle-Math.PI/4)<1e-6,"Desktop native packets use the edited geometry arm count and heading");Stop(this,new());check(File.ReadAllText(selected.SourceFile)==supplied,"Shared geometry UI, history and native execution preserve supplied source");ApplyProject(previous with{Source=source,SourceFile=selected.SourceFile,EntityId=selected.Id,Identities=[],SourceDrafts=[],SelectedSourceFile=null,AdditionalSources=[],LockedNodes=[],CollapsedNodes=[],Layout=[]},null);EditDefinition(document.Definitions.Single(d=>d.Definition!.Label=="StudioSweepDesktopRoot").EntityId);SelectNode(document.AllNodes.Single(n=>n.Kind=="State").Id);BeginNativeCreation(adapter.Primitives.Single(p=>p.Name=="ClockSweep"));check(constructorInputs["sweep"].Text==adapter.SweepGeometrySeed(selected.Id)&&createNativeButton!.IsEnabled,"Native Add uses a compatible XML geometry constructor as its ready-to-use seed");createNativeButton!.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));check(document.AllNodes.Count(n=>n.Kind=="ClockSweep")==2&&adapter.ReadSweepGeometry(document,selectedNode!) is{} added&&adapter.SweepXmlErrors(selected.Id,added.Geometry).Count==0,"Actual Add commits a native clock controller with matching original XML bands");ApplyProject(previous,null);WorkspaceTabs.SelectedIndex=0;
    }
